    """Adaptive-tokenizer confusion memory with exponentially-decayed confusion counts."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, Any]] = []
        # Float-valued counts to allow decay
